@page "/apply"
@rendermode InteractiveServer
@using sv_c44663bf691a4f51bf10b22435037238.Components.Apply
@using sv_c44663bf691a4f51bf10b22435037238.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="text-center mb-4">Job Application</h2>

    <StepIndicator CurrentStep="currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="formState"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="NextStep" />
            break;
        case 1:
            <WorkHistoryStep Model="formState"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep Model="formState"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep Model="formState"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep Model="formState"
                        OnBack="PreviousStep"
                        OnEditStep="GoToStep"
                        SubmitApplication="ApplicationService.SubmitApplicationAsync" />
            break;
    }
</div>

@code {
    private int currentStep;
    private readonly ApplicationFormState formState = new();

    private void NextStep() => currentStep = Math.Min(currentStep + 1, 4);
    private void PreviousStep() => currentStep = Math.Max(currentStep - 1, 0);

    private void GoToStep(int step)
    {
        if (step < currentStep)
            currentStep = step;
    }
}

